"""Export all reviewed independent sources by normal Blender saves through MCP."""
import bpy,json
from pathlib import Path
P=Path('G:/DEV/mask-project-mayhem');A=P/'art_source/Rhino';source=str(A/'Rhino_V1.blend')
assert (A/'final_reviews_COMPLETE').exists(),'Finish the visual and geometry review pipeline before export.'
assert not json.loads((A/'validation_v1.json').read_text())['collision_frames']
jobs=[]
jobs.append({'source_blend':source,'rig':'Rhino_Control','floor':'Review_Floor','manifest':str(A/'vehicle_exports_v1.json'),'components':[
 {'kind':'vehicle','output':str(A/'Rhino_V1_Vehicle.blend'),'scene_name':'Rhino_V1_IndependentVehicle','collections':['Rhino_Truck','Rhino_RearVehicle','Rhino_Interior'],'frame':1,'presentation':{'camera':[12,11,7],'target':[.3,0,2],'lens':52,'focus':[.3,0,1.8],'distance':13},'help_text':'RHINO V1\nRhino_Control : battle_mode 0 route / 1 transforme. Timeline 1-241 : route, deploiement, retour.\nCommandes partielles : bullbar, cannons, rear_detach, rear_open, launcher_up.\nLe lanceur reste bloque tant que la porte arriere nest pas ouverte.\n10 pneus conserves : camion 2 avant + 2 centraux exterieurs ; module 2 centraux interieurs + 4 arriere.\nDimensions et liaisons cachees interpretees depuis les photos fournies. Voir docs/art/Rhino_reference_review_v1.md.\n'},
 {'kind':'rear_vehicle','output':str(A/'Rhino_RearVehicle_V1.blend'),'scene_name':'Rhino_RearVehicle_V1_Independent','collections':['Rhino_RearVehicle'],'frame':151,'bake_driver_objects':['Rhino_RearVehicle_Root','RH_PodSeatBackFold'],'component_offset':[7.7,3.3,0],'ground_z':'asset_min','presentation':{'camera':[4,4,3],'target':[0,0,.85],'lens':55,'focus':[0,0,.8],'distance':4.5},'help_text':'RHINO MODULE ARRIERE V1\nSource autonome, sans cabine ni personnage. Six pneus : deux centraux interieurs et quatre arriere.\nTransformation relative au camion figee en etat separe, composant recentre ; le chassis et ses pieces restent editables.\nCockpit bas et mecanisme de dossier interpretes.\n'}]})
for code,folder,person,rig in [('AS','Alex_Sector','AlexSector','AlexSector_Rig'),('BS','Bruce_Sato','BruceSato','BruceSato_Rig')]:
 out=P/'art_source'/folder
 jobs.append({'source_blend':source,'rig':rig,'floor':'Review_Floor','manifest':str(out/'exports_v1.json'),'components':[
  {'kind':'character','output':str(out/(person+'_V1.blend')),'scene_name':person+'_V1_Independent','collections':[code+'_Character',code+'_Mask'],'frame':1,'properties':{'driving_pose':0,'mask_on':False},'rig_location':[0,0,0],'ground_z':.006,'presentation':{'camera':[3.4,2.9,2.0],'target':[0,0,.94],'lens':65,'focus':[0,0,.95],'distance':3},'help_text':person+' V1\nUn seul personnage, une armature et un visage conserve sous le masque separe.\n'+rig+' > proprietes personnalisees : driving_pose 0 debout / 1 assis ; mask_on vrai/faux.\nInterpretation anatomique des dessins et figurines fournis, sans ressemblance a une personne precise.\nBase anatomique generique CC0 et provenance conservees dans art_source/AnatomyBase et Matt_Trakker.\n'},
  {'kind':'mask','output':str(out/(person+'_Mask_V1.blend')),'scene_name':person+'_Mask_V1_Independent','collections':[code+'_Mask'],'frame':1,'properties':{'driving_pose':0,'mask_on':True},'rig_location':[0,0,0],'detach_mask':True,'origin_bone':'head','socket':person+'_MaskSocket','ground_z':'asset_min','presentation':{'camera':[.85,.67,.42],'target':[.02,0,.08],'lens':62,'focus':[0,0,.1],'distance':.8},'help_text':person+' MASK V1\nMasque autonome : socket avec rest_bind_origin et groupes de poids conserves.\nCoque liee a head, base souple interpretee suivant les poids poitrine/epaules ; rebrancher les groupes sur une armature compatible.\nLa version deja attachee est dans le fichier personnage.\n'}]})
for job in jobs:
 namespace={'EXPORT_JOB':job};exec(compile((P/'art_source/shared_tools/export_components.py').read_text(encoding='utf-8'),'<component_export>','exec'),namespace)
(A/'export_jobs_v1.json').write_text(json.dumps(jobs,indent=2));print('RHINO_ALL_SIX_INDEPENDENT_COMPONENTS_SAVED')
